        /// <summary>
        /// await_primary[expr_ty] (memo): AWAIT a=primary | primary
        /// Handles await expressions and delegates to primary for non-await expressions
        /// </summary>
        public GeneratedExpr? AwaitPrimary()
        {
            // Check for AWAIT token
            if (CurrentToken?.Type == GeneratedTokenType.AWAIT && CurrentToken?.Value == "await")
            {
                Advance(); // consume 'await'
                var primary = ParsePrimary();
                if (primary != null)
                {
                    return _PyAST_Await(primary);
                }
                else
                {
                    throw new InvalidOperationException("Expected primary expression after 'await'");
                }
            }
            else
            {
                // Not an await expression, delegate to primary
                return ParsePrimary();
            }
        }

        // augassign[AugOperator*]: '+=' | '-=' | '*=' | '@=' | '/=' | '%=' | '&=' | '|=' | '^=' | '<<=' | '>>=' | '**=' | '//='
        // Generated method for augassign rule
        public object? Augassign()
        {

            if (CurrentToken?.Type == GeneratedTokenType.OP)
            {
                var op = CurrentToken.Value;
                switch (op)
                {
                    case "+=":
                        Advance();
                        return CreateAugOperator("Add");
                    case "-=":
                        Advance();
                        return CreateAugOperator("Sub");
                    case "*=":
                        Advance();
                        return CreateAugOperator("Mult");
                    case "@=":
                        Advance();
                        return CreateAugOperator("MatMult");
                    case "/=":
                        Advance();
                        return CreateAugOperator("Div");
                    case "%=":
                        Advance();
                        return CreateAugOperator("Mod");
                    case "&=":
                        Advance();
                        return CreateAugOperator("BitAnd");
                    case "|=":
                        Advance();
                        return CreateAugOperator("BitOr");
                    case "^=":
                        Advance();
                        return CreateAugOperator("BitXor");
                    case "<<=":
                        Advance();
                        return CreateAugOperator("LShift");
                    case ">>=":
                        Advance();
                        return CreateAugOperator("RShift");
                    case "**=":
                        Advance();
                        return CreateAugOperator("Pow");
                    case "//=":
                        Advance();
                        return CreateAugOperator("FloorDiv");
                    default:
                        return null;
                }
            }

            return null;
        }
